def compute(vars):
    raw_materials = vars["v1"]
    finished_goods = vars["v2"]
    value = (raw_materials + finished_goods) / 2
    return {
        "value": value,
        "trace": {
            "raw_materials": raw_materials,
            "finished_goods": finished_goods,
            "average": value,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
